require_once __DIR__.'/../includes/functions.php';require_login();require_once __DIR__.'/../config/database.php';$userId=(int)current_user()['user_id'];
$st=$pdo->prepare('SELECT j.job_role_id,j.role_name,j.career_field FROM saved_job_roles sj JOIN job_roles j ON j.job_role_id=sj.job_role_id WHERE sj.user_id=? ORDER BY sj.saved_at DESC');$st->execute([$userId]);$roles=$st->fetchAll();
$st=$pdo->prepare('SELECT p.project_id,p.title,p.description,p.difficulty FROM saved_projects sp JOIN projects p ON p.project_id=sp.project_id WHERE sp.user_id=? ORDER BY sp.saved_at DESC');$st->execute([$userId]);$projects=$st->fetchAll();
$st=$pdo->prepare('SELECT lr.resource_id,lr.title,lr.provider,lr.resource_url FROM saved_resources sr JOIN learning_resources lr ON lr.resource_id=sr.resource_id WHERE sr.user_id=? ORDER BY sr.saved_at DESC');$st->execute([$userId]);$resources=$st->fetchAll();
$pageTitle='Saved items';$active='dashboard';include __DIR__.'/../includes/header.php';?>
<main class="main"><div class="container section-sm"><div class="page-head"><div><span class="eyebrow">Your personal library</span><h1 class="h1">Saved items</h1><p>Keep career roles, projects and learning links you want to revisit.</p></div></div><div class="grid grid-2" style="align-items:start"><section class="card card-pad"><div class="panel-title"><h3>Saved career roles</h3><span class="pill pill-blue"><?=count($roles)?></span></div><?php foreach($roles as $r):?><div class="verified-skill"><div><strong><?=h($r['role_name'])?></strong><p><?=h($r['career_field'])?></p></div><a class="link-arrow" href="<?=h(url('careers/view.php?id='.(int)$r['job_role_id']))?>">Open →</a></div><?php endforeach;?><?php if(!$roles):?><p class="muted small">No career roles saved yet.</p><?php endif;?></section><section class="card card-pad"><div class="panel-title"><h3>Saved projects</h3><span class="pill pill-blue"><?=count($projects)?></span></div><?php foreach($projects as $p):?><div class="verified-skill"><div><strong><?=h($p['title'])?></strong><p><?=h(ucfirst($p['difficulty']))?> · <?=h($p['description'])?></p></div><a class="link-arrow" href="<?=h(url('projects/view.php?id='.(int)$p['project_id']))?>">Open →</a></div><?php endforeach;?><?php if(!$projects):?><p class="muted small">No projects saved yet.</p><?php endif;?></section><section class="card card-pad" style="grid-column:1/-1"><div class="panel-title"><h3>Saved learning resources</h3><span class="pill pill-blue"><?=count($resources)?></span></div><?php foreach($resources as $r):?><div class="verified-skill"><div><strong><?=h($r['title'])?></strong><p><?=h($r['provider'])?></p><a class="link-arrow" href="<?=h($r['resource_url'])?>" target="_blank" rel="noopener noreferrer">Open resource ↗</a></div><form method="post" action="<?=h(url('resources/save.php'))?>"><?=csrf_field()?><input type="hidden" name="resource_id" value="<?=(int)$r['resource_id']?>"><button class="btn btn-outline btn-sm">Remove</button></form></div><?php endforeach;?><?php if(!$resources):?><p class="muted small">No resources saved yet.</p><?php endif;?></section></div></div></main><?php include __DIR__.'/../includes/footer.php';?>
